  timingSafeEqual(derivar(tentativa, SAL), guardado);

console.log(guardado.length, guardado.toString('hex').length);
console.log(confere('cafe-com-leite'));
console.log(confere('cafe-com-leitE'));
console.log(derivar('cafe-com-leite', 'outro-sal').equals(guardado));

