import { createHash } from 'node:crypto';

const hash = (t: string) => createHash('sha256').update(t).digest('hex');
type Linha = { familia: string; usado: boolean; revogado: boolean };
const banco = new Map<string, Linha>();
let seq = 0;

function emitir(familia: string): string {
  const token = `refresh-${++seq}`;
  banco.set(hash(token), { familia, usado: false, revogado: false });
  return token;
}

function renovar(token: string): string {
  const linha = banco.get(hash(token));
  if (!linha || linha.revogado) return 'negado';
  if (linha.usado) {
    for (const l of banco.values()) if (l.familia === linha.familia) l.revogado = true;
    return 'reuso: familia revogada';
  }
  linha.usado = true;
  return emitir(linha.familia);
}

const t1 = emitir('fam-A');
const t2 = renovar(t1);
console.log(t2);
console.log(renovar(t1));
console.log(renovar(t2));
console.log(banco.has(t1));

