const SENSIVEIS = new Set(['senha', 'token', 'authorization', 'cpf']);

function mascarar(valor: unknown): unknown {
  if (Array.isArray(valor)) return valor.map(mascarar);
  if (valor === null || typeof valor !== 'object') return valor;
  const saida: Record<string, unknown> = {};
  for (const [chave, v] of Object.entries(valor)) {
    saida[chave] = SENSIVEIS.has(chave.toLowerCase()) ? '[oculto]' : mascarar(v);
  }
  return saida;
}

