type Claims = { iss: string; aud: string; exp: number; sub: string };

const ESPERADO = { iss: 'https://idp.exemplo.com/realms/casa', aud: 'cockpit-api' };
const AGORA = 1700000500;

function validar(c: Claims): string {
  if (c.iss !== ESPERADO.iss) return 'emissor desconhecido';
  if (c.aud !== ESPERADO.aud) return 'token de outra aplicacao';
  if (c.exp <= AGORA) return 'expirado';
  return `ok: ${c.sub}`;
}

const base = { iss: ESPERADO.iss, aud: 'cockpit-api', exp: 1700000900, sub: 'u1' };

console.log(validar(base));
console.log(validar({ ...base, aud: 'app-de-relatorios' }));
console.log(validar({ ...base, iss: 'https://idp.falso.com/realms/casa' }));
console.log(validar({ ...base, exp: 1700000500 }));

const LIMITE = 3;
const JANELA_MS = 60_000;
const tentativas = new Map<string, number[]>();

function permite(chave: string, agora: number): boolean {
  const recentes = (tentativas.get(chave) ?? []).filter((t) => agora - t < JANELA_MS);
  if (recentes.length >= LIMITE) {
    tentativas.set(chave, recentes);
    return false;
  }
  recentes.push(agora);
  tentativas.set(chave, recentes);
  return true;
}

const login = 'ana@exemplo.com';
const instantes = [0, 1_000, 2_000, 3_000, 30_000, 61_000];
console.log(instantes.map((t) => (permite(login, t) ? 'ok' : '429')).join(' '));
console.log(permite('beto@exemplo.com', 3_500));

